"""Hand-authored bilingual P-v2 candidates; no independent or human approval."""
from pathlib import Path
from datetime import datetime, timezone
import json, hashlib

ROOT = Path.cwd().resolve()
OWN = Path(__file__).parent.resolve()
SOURCE = ROOT / 'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-05/chemie-q1-acids-soaps-preservatives-twenty-current-candidate-v1'
rows = []

def e(id, de, en, performance_de, performance_en):
    return dict(id=id, essentialUnderstandingDe=de, essentialUnderstandingEn=en,
                observablePerformanceDe=performance_de, observablePerformanceEn=performance_en)

def c(id, task_de, task_en, expected_de, expected_en, focus_de, focus_en):
    return dict(id=id, taskDemandDe=task_de, taskDemandEn=task_en,
                expectedPerformanceDe=expected_de, expectedPerformanceEn=expected_en,
                understandingFocusDe=focus_de, understandingFocusEn=focus_en)

def add(id, archetype, expectations, variation_de, variation_en, cases):
    rows.append(dict(goalId=id, reason='Hand authored, content-specific bilingual P-v2 candidate for the frozen future goal. Independent scientific review and current native binding/check pending. E1/G1 ai_candidate/needs_human_review; no observed learner or laboratory performance, human approval or statutory clearance claimed.',
        evidenceLevel='E1', maximumClaimScope='G1', dissent=[], profile=dict(
            archetype=archetype, expectations=expectations,
            coverageExpectations=dict(requiredExpectationIds=[x['id'] for x in expectations],
                alternativeExpectationGroups=[], minimumIndependentDemonstrations=2,
                freshVariationRequired=True, independentTransferRequired=True),
            variationAxes=[dict(id='changed-chemical-case', textDe=variation_de, textEn=variation_en)],
            applicationCaseBriefs=cases)))

add('a3788e40-b540-5bed-be37-b33053528422', 'representation', [
    e('carboxyl-acid-evidence', 'Die Carboxygruppe enthält C=O und O–H am selben Kohlenstoff. Geeignete Beobachtungen belegen den sauren Charakter; Geruch oder ein beliebiges O–H reichen nicht.', 'A carboxyl group has C=O and O–H on the same carbon. Suitable observations support acidity; smell or an arbitrary O–H do not suffice.', 'Carboxygruppen in Struktur- und Skelettformeln markieren und bereitgestellte Indikator-/Reaktionsdaten stoffbezogen deuten.', 'Mark carboxyl groups in structural and skeletal formulas and interpret supplied indicator/reaction data for each substance.'),
    e('homologous-formulas', 'Benachbarte unverzweigte gesättigte Monocarbonsäuren unterscheiden sich um CH₂. Ihre Strukturformeln behalten die Carboxygruppe.', 'Adjacent unbranched saturated monocarboxylic acids differ by CH₂. Their structural formulas retain the carboxyl group.', 'Eine passende homologe Reihe zeichnen und Carbonsäuren von isomeren Estern oder anderen sauerstoffhaltigen Stoffen unterscheiden.', 'Draw a suitable homologous series and distinguish carboxylic acids from isomeric esters or other oxygen-containing compounds.')],
    'Andere Kettenlänge und Darstellungsform; funktionelle Gruppe statt bloßer Summenformel; frische Beobachtungsdaten.', 'Change chain length and representation; functional group rather than molecular formula alone; fresh observation data.', [
    c('three-acids-and-ethanol', 'Gegeben sind HCOOH, CH₃COOH, CH₃CH₂COOH und CH₃CH₂OH sowie Indikatordaten ihrer vergleichbar konzentrierten Lösungen. Markiere Carboxygruppen, begründe die sauren Befunde und zeichne die homologe Reihe.', 'Given HCOOH, CH₃COOH, CH₃CH₂COOH and CH₃CH₂OH with indicator data for comparably concentrated solutions, mark carboxyl groups, explain acidic observations and draw the homologous series.', 'Nur die ersten drei enthalten COOH; ihr CH₂-Zuwachs definiert diese Reihe. Ethanol besitzt OH ohne benachbartes Carbonyl. Die bereitgestellten sauren Indikatorbefunde stützen die Zuordnung, nicht ein bloßer Stoffname.', 'Only the first three contain COOH; their CH₂ increments define this series. Ethanol has OH without an adjacent carbonyl. Supplied acidic indicator observations support the assignment rather than a substance name alone.', 'Gruppenerkennung, Beobachtung und homologe Struktur.', 'Group recognition, observation and homologous structure.'),
    c('butanoic-acid-versus-ester', 'Frisch gegeben sind Skelettformeln von Butansäure und Ethylethanoat, beide C₄H₈O₂. Zeichne vollständige Strukturformeln; ordne getrennte Indikatordaten zu und begründe, weshalb die gleiche Summenformel keine gleiche Stoffklasse beweist.', 'Fresh skeletal formulas show butanoic acid and ethyl ethanoate, both C₄H₈O₂. Draw full structural formulas, assign separate indicator data and explain why equal molecular formulas do not imply the same class.', 'CH₃CH₂CH₂COOH setzt die unverzweigte Reihe fort und besitzt COOH; CH₃COOCH₂CH₃ ist ein Ester ohne Carboxy-OH. Formeln und bereitgestellte Beobachtungen müssen übereinstimmen; keine pauschale Acidität aller sauerstoffhaltigen Stoffe.', 'CH₃CH₂CH₂COOH continues the unbranched series and has COOH; CH₃COOCH₂CH₃ is an ester without a carboxyl OH. Formulas and supplied observations must agree; not all oxygen-containing compounds are acidic.', 'Frischer Isomer-/Darstellungstransfer.', 'Fresh isomer and representation transfer.')])

add('ca216bc6-5205-5b46-abbd-fd5628e4ca5b', 'modeling', [
    e('polar-bond-conjugate-base', 'Die Acidität hängt von der Protonenabgabe und Stabilisierung der konjugierten Base ab. Im Carboxylat ist die negative Ladung mesomer über zwei O-Atome verteilt; beim Alkoholat fehlt diese entsprechende Stabilisierung.', 'Acidity depends on proton donation and stabilization of the conjugate base. Carboxylate charge is resonance-delocalized over two oxygens; the corresponding stabilization is absent in an alkoxide.', 'Polare O–H-Bindung und sinnvolle Grenzstrukturen mit richtigen Ladungen zur Erklärung des Alkohol-/Carbonsäurevergleichs verwenden.', 'Use polar O–H bonds and valid charged resonance contributors to explain the alcohol/carboxylic acid comparison.'),
    e('inductive-strength', 'Elektronenziehende Substituenten können die konjugierte Base induktiv stabilisieren. Der Effekt hängt auch vom Abstand ab; Grenzstrukturen sind keine wechselnden isolierten Moleküle.', 'Electron-withdrawing substituents can inductively stabilize the conjugate base. Distance matters; resonance contributors are not alternating isolated molecules.', 'Bereitgestellte Säurestärkedaten mit induktivem Effekt und Mesomerie begründen, ohne Elektronegativität allein zur universellen Rangregel zu machen.', 'Explain supplied acid-strength data using induction and resonance rather than electronegativity alone as a universal ranking rule.')],
    'Alkohol versus Carbonsäure und frische Substituentenabstände; bereitgestellte pKa-Werte statt Bilderkennung.', 'Alcohol versus carboxylic acid and fresh substituent distances; supplied pKa values rather than image recognition.', [
    c('ethanol-ethanoic-acid', 'Vergleiche Ethanol und Ethansäure mit gegebenen pKa-Werten etwa16 und4,8. Zeichne konjugierte Basen und erkläre den Unterschied anhand Polarität und Mesomerie.', 'Compare ethanol and ethanoic acid with supplied pKa values about16 and4.8. Draw their conjugate bases and explain the difference using polarity and resonance.', 'Ethansäure ist bei kleinerem pKa deutlich stärker. Beide besitzen polare O–H-Bindungen, aber CH₃COO⁻ hat zwei gültige äquivalente Grenzstrukturen mit insgesamt −1; CH₃CH₂O⁻ nicht. Keine zusätzliche Ladung oder O–O-Bindung erfinden.', 'Ethanoic acid is much stronger at lower pKa. Both have polar O–H bonds, but CH₃COO⁻ has two valid equivalent contributors with total charge−1; CH₃CH₂O⁻ does not. Do not invent extra charge or an O–O bond.', 'Konjugierte Base statt bloßes OH-Erkennen.', 'Conjugate base rather than merely recognizing OH.'),
    c('chlorine-distance', 'Gegeben sind Ethansäure, Chloressigsäure und 3-Chlorpropansäure mit pKa4,8/2,9/4,0. Begründe die Rangfolge und zeichne, wie der induktive Einfluss über Bindungen mit größerem Abstand schwächer wird.', 'Given ethanoic, chloroacetic and 3-chloropropanoic acids with pKa4.8/2.9/4.0, explain the ranking and illustrate how the inductive influence through bonds weakens with distance.', 'Alle bilden mesomeriestabilisierte Carboxylate. Der nahe Cl-Substituent zieht Elektronendichte ab und stabilisiert die Base stärker als ein entfernter Cl-Substituent; die Daten passen dazu. Cl erzeugt keine neue Mesomeriebrücke durch gesättigte CH₂-Gruppen.', 'All form resonance-stabilized carboxylates. Nearby Cl withdraws electron density and stabilizes the base more strongly than distant Cl, matching the data. Cl does not create a resonance bridge through saturated CH₂ groups.', 'Induktiver Abstandstransfer.', 'Transfer of inductive distance effects.')])

add('70b34ae7-4481-590c-9a02-516464750832', 'concept', [
    e('condensation-evidence', 'Alkohol und Carbonsäure können unter geeigneten Bedingungen Ester und Wasser bilden. Zusammensetzung, Nachweisdaten und Stoffbilanz tragen die Schlussfolgerung; Geruch allein identifiziert keinen Ester.', 'Alcohol and carboxylic acid can form ester and water under suitable conditions. Composition, detection data and balance support the inference; odor alone does not identify an ester.', 'Bereitgestellte experimentelle Daten auswerten und eine passende Kondensationsgleichung mit richtiger Esterbindung formulieren.', 'Interpret supplied experimental data and write a matching condensation equation with the correct ester linkage.'),
    e('properties-and-use', 'Ester haben polare Gruppen, aber einfache Ester ohne weitere OH-Gruppe sind untereinander keine Wasserstoffbrückendonoren. Größe und gesamte Struktur beeinflussen Stoffeigenschaften und Einsatz.', 'Esters have polar groups, but simple esters without another OH are not hydrogen-bond donors to each other. Size and overall structure affect properties and use.', 'Gegebene Löslichkeits-/Siededaten durch Wechselwirkungen erklären und passende Alltags-/Technikverwendungen begründen.', 'Explain supplied solubility/boiling data through interactions and justify suitable everyday/technical uses.')],
    'Frische Alkohol-/Säurekombination und Wechselwirkung-/Anwendungsdaten; keine pauschalen Duft-, Löslichkeits- oder Siederegeln.', 'Fresh alcohol/acid combination and interaction/use data; no universal smell, solubility or boiling rules.', [
    c('ethyl-ethanoate-observations', 'Ein Versuchsprotokoll weist nach Umsetzung von Ethansäure/Ethanol Ethylethanoat und Wasser nach. Gegeben sind dessen begrenzte Wassermischbarkeit und niedrigere Siedetemperatur gegenüber Ethansäure. Formuliere die Reaktion und begründe Eigenschaften sowie einen angegebenen Lösungsmitteleinsatz.', 'A supplied experiment detects ethyl ethanoate and water after reacting ethanoic acid/ethanol. Limited water miscibility and a lower boiling point than ethanoic acid are supplied. Write the reaction and explain properties and a stated solvent use.', 'CH₃COOH + HOCH₂CH₃ ⇌ CH₃COOCH₂CH₃ + H₂O ist ausgeglichen. Ester akzeptiert Wasserstoffbrücken von Wasser, spendet ohne OH jedoch keine; unpolarer Anteil begrenzt Mischbarkeit. Aus den vorgegebenen Eigenschaften wird der Lösungsmitteleinsatz begründet, keine generelle Harmlosigkeit.', 'CH₃COOH + HOCH₂CH₃ ⇌ CH₃COOCH₂CH₃ + H₂O is balanced. The ester accepts hydrogen bonds from water but cannot donate without OH; its nonpolar part limits miscibility. Supplied properties justify solvent use, not general harmlessness.', 'Reaktionsschluss und Struktur-Eigenschaft-Nutzung.', 'Reaction inference and structure/property/use link.'),
    c('methyl-butanoate-transfer', 'Neue Daten betreffen Butansäure/Methanol: Produktanalyse zeigt Methylbutanoat und Wasser; eine Anwendungstabelle nennt Aromakomponente und organisches Extraktionsmittel. Zeichne Produkt und verknüpfe die jeweiligen bereitgestellten Eigenschaften mit Anwendungen.', 'Fresh butanoic acid/methanol data identify methyl butanoate and water; a use table lists an aroma component and an organic extraction solvent. Draw the product and link supplied properties to uses.', 'CH₃CH₂CH₂COOH + CH₃OH ⇌ CH₃CH₂CH₂COOCH₃ + H₂O. Die Alkoholseite wird nicht als Kohlenstoff direkt am Carbonyl angehängt. Polare Estergruppe/unpolare Kette erklären begrenzte Wassermischbarkeit; Geruchs- und Verteilungsdaten tragen unterschiedliche Anwendungen, keine eigenständige Verkostung.', 'CH₃CH₂CH₂COOH + CH₃OH ⇌ CH₃CH₂CH₂COOCH₃ + H₂O. The alcohol portion is not attached as carbon directly to the carbonyl. Polar ester/nonpolar chain explain limited water miscibility; odor and partition data support distinct uses, without tasting.', 'Andere Esterstruktur und Anwendungsdaten.', 'Different ester structure and use data.')])

add('667bc303-e9b8-570b-84f1-61cc8bdfd006', 'concept', [
    e('acidic-equilibrium', 'Veresterung und saure Hydrolyse bilden ein reversibles System. Bedingungen und Mengen beeinflussen den Gleichgewichtszustand; Katalyse verändert nicht dessen Stoffbilanz.', 'Esterification and acidic hydrolysis form a reversible system. Conditions and amounts affect equilibrium; catalysis does not change its stoichiometry.', 'Passende Hin-/Rückgleichungen bilanzieren und bereitgestellte Ester-/Wasserdaten als reversible Umsetzungen deuten.', 'Balance matching forward/reverse equations and interpret supplied ester/water data as reversible conversions.'),
    e('alkaline-carboxylate', 'Alkalische Hydrolyse verbraucht Hydroxid und liefert Carboxylat sowie Alkohol. Unter diesen Bedingungen wird die Carbonsäure abgefangen; die Rückveresterung ist praktisch unterdrückt.', 'Alkaline hydrolysis consumes hydroxide and produces carboxylate and alcohol. Under these conditions the acid is trapped, practically suppressing reverse esterification.', 'Alkalischen und sauren Fall über Stoff-/Ladungsbilanz unterscheiden und eine passende Alltagsbeobachtung begründen.', 'Distinguish alkaline and acidic cases using atom/charge balance and explain a suitable everyday observation.')],
    'pH-/Reaktionsbedingungen und neue Esterbausteine; Gleichgewicht nicht mit alkalischer Verseifung gleichsetzen.', 'Change pH/conditions and ester components; do not equate acidic equilibrium with alkaline saponification.', [
    c('ethyl-ethanoate-acid-versus-base', 'Vergleiche bereitgestellte Protokolle für Ethylethanoat mit saurem Wasser beziehungsweise OH⁻. Formuliere Produkte und erkläre die im zweiten Fall beobachtete Carboxylatbildung.', 'Compare supplied ethyl ethanoate protocols with acidic water versus OH⁻. Write products and explain carboxylate formation in the second case.', 'Saure Hydrolyse: Ester + H₂O ⇌ CH₃COOH + Ethanol. Alkalisch: CH₃COOCH₂CH₃ + OH⁻ → CH₃COO⁻ + Ethanol. OH⁻ ist im zweiten Nettofall Reaktionspartner; die Ladung−1 bleibt erhalten. Kein Salz als neutraler Ester oder universell identisches Gleichgewicht.', 'Acidic hydrolysis: ester + H₂O ⇌ CH₃COOH + ethanol. Alkaline: CH₃COOCH₂CH₃ + OH⁻ → CH₃COO⁻ + ethanol. OH⁻ is a net reactant in the second case; charge−1 is conserved. Salt is not a neutral ester or an identical equilibrium.', 'Reaktionsbedingungen und Carboxylatfalle.', 'Conditions and carboxylate trapping.'),
    c('propyl-butanoate-cleaning-model', 'Ein Modell einer alkalischen Fett-/Esterreinigung verwendet Propylbutanoat statt Ethylethanoat. Bestimme Produkte und begründe mit einem sauren Vergleichsfall, weshalb eine Esterabnahme nicht allgemein dieselbe Rückreaktion erwarten lässt.', 'An alkaline ester-cleaning model uses propyl butanoate instead of ethyl ethanoate. Determine products and use an acidic comparison to explain why ester loss does not always imply the same reverse reaction.', 'Propylbutanoat + OH⁻ → Butanoat + Propan-1-ol; die vier C der Säure und drei C des Alkohols bleiben den richtigen Produkten zugeordnet. Ein saurer Fall liefert Butansäure/Alkohol reversibel, alkalisch fehlt die freie Säure für unmittelbare Rückveresterung.', 'Propyl butanoate + OH⁻ → butanoate + propan-1-ol; the acid four carbons and alcohol three carbons stay assigned correctly. The acidic case yields butanoic acid/alcohol reversibly; the alkaline case lacks free acid for direct reverse esterification.', 'Frische Stoffbilanz im Anwendungsmodell.', 'Fresh balance in an application model.')])

add('4da0839d-ab6d-53c1-ac21-c9872555ae16', 'representation', [
    e('nucleophilic-acyl-steps', 'OH⁻ greift den elektrophilen Carbonylkohlenstoff an; eine tetraedrische Zwischenstufe und anschließende Abspaltung beschreiben nukleophile Acylsubstitution.', 'OH⁻ attacks electrophilic carbonyl carbon; a tetrahedral intermediate and subsequent elimination describe nucleophilic acyl substitution.', 'Elektronenpaarpfeile, Bindungsänderungen, Zwischenstufen und Ladungen eines vorgegebenen alkalischen Estermechanismus korrekt darstellen.', 'Correctly show electron-pair arrows, bond changes, intermediates and charges for a supplied alkaline ester mechanism.'),
    e('final-proton-transfer', 'Protonenübertragung liefert Carboxylat und Alkohol. Das Nettoschema verbraucht OH⁻ und erklärt, weshalb unter alkalischen Bedingungen freie Carbonsäure nicht das Endprodukt ist.', 'Proton transfer gives carboxylate and alcohol. The net scheme consumes OH⁻ and explains why free carboxylic acid is not the alkaline endpoint.', 'Mechanismus und Nettobilanz verbinden und einen mechanistisch falschen oder unvollständigen Vorschlag begründet korrigieren.', 'Connect mechanism to net balance and correct a mechanistically wrong or incomplete proposal with reasons.')],
    'Andere Esterseiten, fehlerhafte Pfeile/Ladungen oder fehlender Protonenschritt; keine reinen auswendig gelernten Bildkopien.', 'Different ester groups, wrong arrows/charges or missing proton step; no mere memorized diagram copying.', [
    c('ethyl-ethanoate-mechanism', 'Skizziere für Ethylethanoat/OH⁻ Angriff, tetraedrische Zwischenstufe, Kollaps und Protonenübertragung. Prüfe Ladung und Stoffbilanz jedes Schritts.', 'Sketch OH⁻ attack, tetrahedral intermediate, collapse and proton transfer for ethyl ethanoate. Check charge and atom balance at every step.', 'Pfeil vom freien Elektronenpaar des OH⁻ zum Carbonyl-C, π-Elektronen zu O; Zwischenstufe CH₃C(OH)(O⁻)(OEt). Rückbildung C=O verdrängt Ethoxid; CH₃COOH überträgt H⁺ auf Ethoxid. Endprodukte CH₃COO⁻/Ethanol, netto OH⁻ verbraucht.', 'Arrow from OH⁻ lone pair to carbonyl C, π electrons to O; intermediate CH₃C(OH)(O⁻)(OEt). Re-forming C=O expels ethoxide; CH₃COOH protonates ethoxide. Final CH₃COO⁻/ethanol, with net OH⁻ consumption.', 'Elektronenfluss und terminaler Protonenschritt.', 'Electron flow and terminal proton step.'),
    c('methyl-propanoate-error-transfer', 'Ein frischer Vorschlag für Methylpropanoat zeigt OH⁻-Angriff am Methyl-C, eine positive tetraedrische O-Zwischenstufe und Propansäure als alkalisches Endprodukt. Korrigiere den vorgegebenen Acylhydrolyseweg und begründe die Änderungen.', 'A fresh methyl propanoate proposal shows OH⁻ attack at methyl C, a positive tetrahedral O intermediate and propanoic acid as alkaline endpoint. Correct the specified acyl-hydrolysis pathway and explain changes.', 'Im verlangten Acylweg erfolgt Angriff am Carbonyl-C, das ehemalige Carbonyl-O trägt −1. Nach Kollaps entsteht Methoxid; Protonenübertragung liefert Propanoat/Methanol. Angriffsort, Elektronenquelle und Ladungsbilanz werden erklärt, nicht nur Endprodukte ersetzt.', 'For the specified acyl pathway attack is at carbonyl C; the former carbonyl O has charge−1. Collapse yields methoxide; proton transfer gives propanoate/methanol. Explain site, electron source and charge balance rather than merely swapping products.', 'Mechanistische Fehlerdiagnose bei neuem Ester.', 'Mechanistic error diagnosis for another ester.')])

add('9d97f628-c3ea-5dc0-8723-b17b16297af3', 'modeling', [
    e('alcohol-exchange-plan', 'Transesterifizierung tauscht den Alkoholrest eines Esters durch einen anderen Alkohol aus. Sie bildet im idealen Nettofall keinen Wasser-Nebenproduktstrom.', 'Transesterification exchanges an ester alcohol group using another alcohol. The ideal net reaction does not produce water.', 'Aus bereitgestellten Stoffen ein geeignetes Reaktions-/Trennkonzept mit ausgeglichener Gleichung planen.', 'Plan a suitable reaction/separation concept from supplied substances with a balanced equation.'),
    e('equilibrium-intervention', 'Alkoholüberschuss oder Produktentzug kann bei gegebenen Bedingungen die Gleichgewichtslage beeinflussen. Ein Katalysator verändert die Geschwindigkeit, nicht die thermodynamische Gleichgewichtskonstante.', 'Alcohol excess or product removal can affect equilibrium under given conditions. A catalyst changes rate, not the thermodynamic equilibrium constant.', 'Alternative Pläne über Mengen, Gleichgewicht und bereitgestellte Trennbedingungen beurteilen, ohne reale Ausbeute zu erfinden.', 'Evaluate plans using amounts, equilibrium and supplied separation conditions without inventing real yields.')],
    'Andere Alkohole und Ester bis zu einem vorgegebenen Fettmodell; Mengenüberschuss versus Produktentzug statt gleicher Zahleneinsetzung.', 'Different alcohols/esters up to a supplied fat model; excess versus product withdrawal rather than simple numeric substitution.', [
    c('methyl-ethanoate-ethanol-plan', 'Plane im bereitgestellten geschlossenen Modell Methylacetat/Ethanol → Ethylacetat/Methanol. Bei idealisiertem K=1 vergleiche äquimolaren Start mit vierfachem Ethanol; unterscheide Katalyse vom Gleichgewichtseingriff.', 'Plan supplied closed-model methyl acetate/ethanol → ethyl acetate/methanol. At idealized K=1 compare equimolar start with fourfold ethanol; distinguish catalysis from equilibrium intervention.', 'Ausgeglichener Resttausch ohne Wasser. Äquimolar ergeben sich modellhaft0,5molUmsatz aus1molEster; mit4molEthanol0,8mol, da x²/((1−x)(4−x))=1. Das ist Modellvorhersage, keine gemessene Ausbeute; Katalysator erhöht nicht K.', 'Balanced group exchange without water. Model conversion is0.5mol from1mol ester equimolarly, versus0.8mol with4mol ethanol because x²/((1−x)(4−x))=1. This is model prediction, not measured yield; catalyst does not increase K.', 'Mengen-/Gleichgewichtsplanung.', 'Amount and equilibrium planning.'),
    c('triglyceride-methanol-product-withdrawal', 'Frisch gegeben sind ein Triglycerid, Methanol und Daten zur Abtrennung von Glycerin. Formuliere das idealisierte Umesterungsschema und vergleiche Alkoholüberschuss mit Produktabtrennung; kein eigenständiger Gefahrstoffversuch.', 'Fresh inputs are a triglyceride, methanol and glycerol-separation data. Write the idealized exchange scheme and compare alcohol excess with product removal; no unsupervised hazardous experiment.', 'Triglycerid +3Methanol ⇌3Fettsäuremethylester +Glycerin. Beide bereitgestellten Eingriffe können den Umsatz begünstigen; Trennbarkeit und Nebenreaktionsdaten begrenzen den Plan. Es entstehen nicht Fettsäuresalze wie bei alkalischer Hydrolyse, und keine garantierte100%-Ausbeute.', 'Triglyceride +3methanol ⇌3fatty-acid methyl esters +glycerol. Both supplied interventions can favor conversion; separation and side-reaction data constrain the plan. Products are not carboxylate salts as in alkaline hydrolysis, and100%yield is not guaranteed.', 'Frisches Fett-/Trennkonzept.', 'Fresh fat and separation concept.')])

add('6765f741-42a6-55c5-a218-81b883b1f5ae', 'experiment', [
    e('perform-saponification', 'Fett besitzt drei Esterbindungen am Glycerin. Alkalische Hydrolyse liefert Glycerin und Fettsäuresalze; Herstellung verlangt passende Durchführung und Beobachtung.', 'Fat has three ester bonds on glycerol. Alkaline hydrolysis yields glycerol and fatty-acid salts; preparation requires suitable execution and observation.', 'Eine zugelassene betreute Versuchsvorschrift eigenständig sachgerecht ausführen, Arbeitsschritte/Beobachtungen dokumentieren und Produkte über Esterstruktur/Bilanz erklären.', 'Independently carry out an approved supervised protocol, document steps/observations and explain products using ester structure and balance.'),
    e('salt-out-separate', 'Zugabe von geeignetem Salz kann Seife aus der wässrigen Phase aussalzen. Glycerin und gelöste Stoffe werden dadurch nicht automatisch ebenfalls zu festen Seifenprodukten.', 'Adding a suitable salt can salt soap out of the aqueous phase. Glycerol and dissolved substances do not thereby automatically become solid soap products.', 'Aussalzen und Trennung im betreuten Versuch durchführen und den Verbleib der Phasen/Stoffe anhand eigener Beobachtungen begründen.', 'Perform salting-out and separation in a supervised experiment and justify phase/substance locations from actual observations.')],
    'Vorgegebene Fette/Protokolle und kontrollierter Salzvergleich; reale Durchführung bleibt zukünftiges Leistungsmerkmal, vorgelegte Logs allein beweisen sie nicht.', 'Supplied fats/protocols and controlled salt comparison; actual execution remains a future performance requirement, not proved by supplied logs alone.', [
    c('supervised-triolein', 'Führe unter Aufsicht eine freigegebene Seifenherstellung aus vorgegebenem Triolein/NaOH mit anschließendem Aussalzen aus; keine selbst festgelegten Gefahrstoffmengen. Dokumentiere Handgriffe, Phasentrennung und erkläre die Produkte.', 'Under supervision perform an approved soap preparation from supplied triolein/NaOH followed by salting-out; no self-prescribed hazardous amounts. Document actions, phase separation and explain products.', 'Zukünftige Leistungsbelege umfassen sachgerechte eigene Durchführung und Beobachtung, nicht nur Protokollnacherzählung. Triolein +3NaOH →Glycerin +3Natriumoleat; Esterbindungen werden gespalten. Ausgesalzene Seife getrennt, Glycerin überwiegend wässrig; fehlende Trennung wird nicht als Erfolg behauptet.', 'Future evidence includes correct actual execution/observation, not merely retelling a protocol. Triolein +3NaOH →glycerol +3sodium oleate; ester bonds cleave. Salted-out soap is separated, glycerol mainly aqueous; failed separation is not claimed successful.', 'Eigene betreute Herstellung und Stoffschluss.', 'Actual supervised preparation and inference.'),
    c('tristearin-salt-control', 'Eine frische freigegebene Aufgabe verwendet Tristearin und vergleicht nach gleicher Hydrolyse Ansätze mit/ohne Salzzugabe. Führe die erlaubten Trennschritte betreut aus; begründe, warum Salzzugabe nicht selbst Fett zu Seife umsetzt.', 'A fresh approved task uses tristearin and compares batches after identical hydrolysis with/without salt addition. Perform permitted separation steps under supervision; explain why salt addition itself does not turn fat into soap.', 'Tristearin +3NaOH →Glycerin +3Natriumstearat. Der kontrollierte Salzvergleich betrifft Löslichkeit/Trennung bereits gebildeter Seife, nicht eine neue Fettspaltung. Eigene Handgriffe und Phasenbeobachtungen tragen den Durchführungsbeleg; ein Datensatz allein erfüllt den praktischen Operator nicht.', 'Tristearin +3NaOH →glycerol +3sodium stearate. Controlled salt comparison concerns solubility/separation of existing soap, not new fat cleavage. Actual actions and phase observations evidence execution; a dataset alone does not satisfy the practical operator.', 'Anderes Fett und Trennkontrolle.', 'Different fat and separation control.')])

add('6966df95-f125-5ecc-af8e-0442545d9f17', 'modeling', [
    e('amphiphilic-interface', 'Seifen besitzen hydrophile Carboxylatköpfe und hydrophobe Kohlenwasserstoffreste. Ihre Anordnung hängt davon ab, welche Seite der Grenzfläche Wasser berührt.', 'Soaps have hydrophilic carboxylate heads and hydrophobic hydrocarbon tails. Their arrangement depends on which side of the interface touches water.', 'Kopf und Rest in einer Struktur markieren und Moleküle an Luft/Wasser- und Öl/Wasser-Grenzflächen begründet ausrichten.', 'Mark head and tail in a structure and justify molecular orientations at air/water and oil/water interfaces.'),
    e('micelles-emulsion-surface', 'In einer normalen wässrigen Micelle weisen hydrophobe Reste überwiegend nach innen und Köpfe nach außen. Tenside können Öl dispergieren und die Oberflächenspannung verringern; Dispersion ist keine chemische Auflösung oder Fettspaltung.', 'In a normal aqueous micelle hydrophobic tails mainly point inward and heads outward. Surfactants can disperse oil and lower surface tension; dispersion is not chemical dissolution or fat cleavage.', 'Micellen, emulgierte Öltröpfchen und Luft/Wasser-Grenzflächen unterscheiden und bereitgestellte Dispersions-/Oberflächenspannungsdaten mit der Struktur erklären.', 'Distinguish micelles, emulsified oil droplets and air/water interfaces and explain supplied dispersion/surface-tension data using structure.')],
    'Andere Grenzflächen und umgekehrte Phasenlage; Molekülorientierung aus den berührenden Phasen statt aus einer auswendig gelernten Kreiszeichnung.', 'Change interfaces and reverse phase geometry; infer molecular orientation from contacting phases instead of memorizing a circular drawing.', [
    c('oil-in-water-and-surface', 'Zeichne die Anordnung einer vorgegebenen Seife an Luft/Wasser und um ein Öltröpfchen in Wasser. Erkläre zusätzlich eine normale wässrige Micelle sowie bereitgestellte Daten mit/ohne Tensid: Öl bleibt länger verteilt und die Oberflächenspannung sinkt.', 'Draw a supplied soap at air/water and around an oil droplet in water. Explain a normal aqueous micelle and supplied with/without-surfactant data: oil remains dispersed longer and surface tension falls.', 'Köpfe berühren Wasser, Reste Luft bzw. Öl; in der normalen Micelle liegen Reste innen. Das stabilisierte dispergierte Öl bleibt eine getrennte Phase. An der Oberfläche verändern adsorbierte Tenside die Grenzflächenenergie; weder Seifenbildung noch Fettspaltung ist erforderlich.', 'Heads contact water, tails air or oil; normal micelle tails point inward. Stabilized dispersed oil remains a separate phase. Adsorbed surfactants change interfacial energy; neither soap production nor fat cleavage is required.', 'Grenzfläche, Micelle und Wirkung verbunden erklären.', 'Connect interface, micelle and action.'),
    c('water-drop-in-oil-interface', 'Frisch gegeben ist ein hypothetisches Wassertröpfchen in einer zusammenhängenden Ölphase. Sage allein aus der amphiphilen Struktur die bevorzugte Orientierung einer Seife an dieser Grenzfläche voraus und begründe, warum damit noch keine stabile inverse Micelle oder Emulsion bewiesen ist.', 'A fresh hypothetical water droplet sits in continuous oil. Predict only the preferred interfacial soap orientation from amphiphilic structure and explain why this does not prove a stable inverse micelle or emulsion.', 'Köpfe richten sich zum Wassertröpfchen, Reste zur äußeren Ölphase. Die Orientierung folgt aus Phasenkontakt; Stabilität erfordert zusätzliche Bedingungen/Daten und ist nicht bei jeder Seife garantiert. Die normale wässrige Micelle ist anders orientiert.', 'Heads face the water droplet, tails the surrounding oil. Phase contact explains orientation; stability needs additional conditions/data and is not guaranteed for every soap. A normal aqueous micelle has the opposite geometry.', 'Frischer Phasen-/Modellgrenzentransfer.', 'Fresh phase and model-limit transfer.')])

add('e874ee60-4569-5830-81bf-11f86f0c63ac', 'concept', [
    e('surfactant-structure-classes', 'Seifen sind Fettsäuresalze mit Carboxylatkopf. Andere Tenside können etwa Sulfonatköpfe oder ungeladene hydrophile Gruppen besitzen; alle besitzen einen passenden hydrophoben Anteil.', 'Soaps are fatty-acid salts with carboxylate heads. Other surfactants may have sulfonate heads or uncharged hydrophilic groups; all have a suitable hydrophobic part.', 'Vorgegebene Strukturen als Seife oder anderes anionisches/nichtionisches Tensid einordnen und die Zuordnung an funktionellen Gruppen begründen.', 'Classify supplied structures as soap or another anionic/nonionic surfactant and justify with functional groups.'),
    e('conditional-benefits-limits', 'Eignung hängt von Struktur, Wasserhärte, pH, Temperatur, Dosierung und weiteren bereitgestellten Stoffdaten ab. Modern oder natürlich allein beweist weder gute Waschwirkung noch Umweltverträglichkeit.', 'Suitability depends on structure, hardness, pH, temperature, dose and other supplied substance data. Modern or natural alone proves neither good cleaning nor environmental compatibility.', 'Für konkrete vorgegebene Bedingungen Vor-/Nachteile fachlich abwägen und unbelegte Verallgemeinerungen über Sicherheit oder Abbaubarkeit vermeiden.', 'Weigh advantages/disadvantages under specific supplied conditions and avoid unsupported generalizations about safety or biodegradability.')],
    'Anderer Tensidkopf, Wasserhärte und temperaturabhängige Stoffdaten; Entscheidungskriterien statt pauschale Rangfolge.', 'Change surfactant heads, water hardness and temperature-dependent data; use decision criteria rather than a blanket ranking.', [
    c('soap-and-sulfonate-hard-water', 'Vergleiche Natriumstearat CH₃(CH₂)₁₆COO⁻Na⁺ mit einem vorgegebenen Alkylsulfonat RSO₃⁻Na⁺. Daten zeigen im jeweiligen Modell schwer lösliche Calciumseife, aber kein entsprechendes Sulfonatpräzipitat. Begründe die Stoffklassen und eine begrenzte Empfehlung für hartes Wasser.', 'Compare sodium stearate CH₃(CH₂)₁₆COO⁻Na⁺ with supplied alkyl sulfonate RSO₃⁻Na⁺. Model data show poorly soluble calcium soap but no corresponding sulfonate precipitate. Explain classes and a bounded recommendation for hard water.', 'Carboxylat versus Sulfonat identifiziert Seife versus anderes anionisches Tensid. Calcium entfernt Seifenanionen als schwer lösliches Salz; das gegebene Sulfonat hat hier einen Vorteil. Daraus folgen keine allgemeine Ungiftigkeit, gesetzliche Zulassung oder Abbaubarkeit aller Sulfonate.', 'Carboxylate versus sulfonate identifies soap versus another anionic surfactant. Calcium removes soap anions as an insoluble salt; the supplied sulfonate has an advantage here. This does not imply universal harmlessness, legal approval or biodegradability of all sulfonates.', 'Struktur und bedingter Stoffvergleich.', 'Structure and conditional comparison.'),
    c('nonionic-temperature-selection', 'Eine frische Tabelle vergleicht Seife, Alkylsulfonat und ein nichtionisches Tensid mit vorgegebener Polyetherkopfgruppe bei 20 und 60 °C. Das nichtionische Tensid trübt oberhalb einer angegebenen Temperatur; Wasch-, Härte- und Abbaudaten sind getrennt. Wähle für das vorgegebene Waschziel und benenne einen Nachteil deiner Wahl.', 'A fresh table compares soap, alkyl sulfonate and a nonionic surfactant with a supplied polyether head at20 and60 °C. The nonionic surfactant clouds above a stated temperature; cleaning, hardness and degradation data are separate. Choose for the specified cleaning goal and identify a disadvantage.', 'Der nichtionische Kopf ist hydrophil ohne Ionenladung; Trübung kann die temperaturabhängige Anwendung begrenzen. Auswahl und Nachteil folgen aus den konkreten Tabellendaten, nicht aus modern/natürlich oder allein der Ladung. Fehlende Daten werden als fehlend benannt.', 'The nonionic head is hydrophilic without ionic charge; clouding can constrain temperature-dependent use. Choice and disadvantage follow the table rather than modern/natural labels or charge alone. Missing data remain missing.', 'Frischer Kriterien-/Temperaturtransfer.', 'Fresh criterion and temperature transfer.')])

add('1837690e-cfb1-5b1c-96c8-0fb40d6d5d69', 'modeling', [
    e('concentration-dispersion', 'Tensidkonzentration beeinflusst Grenzflächenbelegung, Micellenbildung und Dispergierung. Mehr Tensid oder mehr Schaum bedeutet nicht unbegrenzt bessere Reinigung.', 'Surfactant concentration affects interfacial adsorption, micelle formation and dispersion. More surfactant or foam does not mean indefinitely better cleaning.', 'Bereitgestellte Konzentrations-/Dispersionsdaten unter vorgegebenen Bedingungen erklären und sinnvolle Dosierungen begründen.', 'Explain supplied concentration/dispersion data under specified conditions and justify sensible doses.'),
    e('hardness-temperature-factors', 'Calcium- und Magnesiumionen können mit Seifen schwer lösliche Kalkseifen bilden und verfügbare Seifenanionen vermindern. Temperatur beeinflusst Lösung, Beweglichkeit und die jeweils gegebenen Stoffeigenschaften; ihre Wirkung ist nicht universell monoton.', 'Calcium and magnesium can precipitate poorly soluble soaps and reduce available soap anions. Temperature affects dissolution, motion and specified material properties; its effect is not universally monotonic.', 'Härte und Temperatur von Konzentration als unabhängige Faktoren unterscheiden, Calciumseifenbildung bilanzieren und einen kontrollierten Vergleich deuten.', 'Separate hardness and temperature from concentration, balance calcium-soap formation and interpret a controlled comparison.')],
    'Neue kontrollierte Kombinationen von Härte, Temperatur und Konzentration; Daten erklären und jeweils nur einen Faktor variieren.', 'Use fresh controlled combinations of hardness, temperature and concentration; explain data and vary one factor at a time.', [
    c('soap-hardness-concentration-series', 'Gegeben sind gleiche Ölverschmutzung und Temperatur. In weichem Wasser verbessert eine Seifenkonzentrationsreihe die Dispersion bis zu einem Plateau; bei Ca²⁺ treten Niederschlag und schwächere Dispersion auf. Erkläre Micellen/Dispergierung und formuliere die Calciumseifenreaktion.', 'At equal oil contamination and temperature, a soft-water soap concentration series improves dispersion up to a plateau; Ca²⁺ produces precipitate and poorer dispersion. Explain micelles/dispersion and write calcium-soap formation.', '2 RCOO⁻ + Ca²⁺ → Ca(RCOO)₂(s) ist ladungs- und stoffbilanziert. Präzipitation vermindert verfügbare Seife. Die Konzentrationsdaten passen zu Grenzflächenbelegung/Micellen; ein Plateau und Schaum allein sind kein Beleg unbegrenzter Reinigung.', '2 RCOO⁻ + Ca²⁺ → Ca(RCOO)₂(s) balances charge and atoms. Precipitation reduces available soap. Concentration data fit adsorption/micelles; a plateau and foam alone do not prove unlimited cleaning.', 'Härte und Konzentration mechanistisch verbinden.', 'Connect hardness and concentration mechanistically.'),
    c('controlled-temperature-replan', 'Eine neue Tabelle variiert bei gleichem Tensid, Wasser und Schmutz getrennt Temperatur und Dosis. Moderate Erwärmung verbessert im Modell die Dispersion, oberhalb einer vorgegebenen Stoffgrenze nimmt sie ab; zusätzliche Dosis hilft nur in einem Bereich. Erkläre die Daten und plane einen Vergleich, der Härte als Ursache prüft.', 'A fresh table varies temperature and dose separately at equal surfactant, water and soil. Moderate warming improves model dispersion, above a supplied material limit it declines; extra dose helps only within a range. Explain data and plan a comparison testing hardness.', 'Löslichkeit/Beweglichkeit und die vorgegebene Stoffgrenze erklären die Temperaturdaten; Konzentration wirkt über verfügbare Grenzflächen-/Micellenbildung. Für den Härtevergleich bleiben Temperatur, Dosis und Schmutz gleich, nur Ca/Mg-Gehalt ändert sich. Keine universelle Regel heißer=immer besser oder Schaum=Waschwirkung.', 'Solubility/mobility and the supplied material limit explain temperature data; dose acts through available interfacial/micelle formation. A hardness comparison fixes temperature, dose and soil while changing Ca/Mg. No universal hotter-is-better or foam-equals-cleaning rule.', 'Frischer Mehrfaktor-/Kontrolltransfer.', 'Fresh multiple-factor and control transfer.')])

add('8a491e3b-5d0b-51d3-9b14-0977ec035dd6', 'modeling', [
    e('hardness-ion-classes', 'Gesamthärte bezieht sich auf Calcium-/Magnesiumionen. Hydrogencarbonatanteile tragen zur temporären, andere geeignete Gegenionen zur permanenten Härte bei; Gegenionen allein ohne Härtebildner erzeugen keine Wasserhärte.', 'Total hardness concerns calcium/magnesium ions. Hydrogencarbonate portions contribute temporary hardness and other suitable counterions permanent hardness; counterions alone without hardness cations do not create hardness.', 'Aus gegebenen Ionen-/Salzdaten temporäre, permanente und Gesamthärte im ausdrücklich vereinfachten Modell zuordnen und unterscheiden.', 'Classify temporary, permanent and total hardness from supplied ion/salt data in an explicitly simplified model.'),
    e('softening-process-limit', 'Erhitzen kann einen Calciumhydrogencarbonatanteil als Calciumcarbonat entfernen. Ionenaustausch kann Härtebildner gegen Natrium ersetzen; enthärtetes Wasser ist deshalb nicht notwendig entsalzt.', 'Heating can remove a calcium hydrogencarbonate portion as calcium carbonate. Ion exchange can replace hardness cations with sodium; softened water is therefore not necessarily demineralized.', 'Geeignete Verfahren aus der konkreten Ionenlage auswählen, Reaktionen/Austausch ladungsrichtig erklären und die jeweilige Resthärte oder verbleibenden Ionen beurteilen.', 'Select suitable processes from the ion composition, explain reactions/exchange with correct charge balance and assess remaining hardness or ions.')],
    'Hydrogencarbonat-/Sulfat-/Chloridgemische und Wechsel von Erhitzen zu Natrium-Ionenaustausch; Stoff-/Ladungsbilanzen und Grenzen.', 'Use hydrogencarbonate/sulfate/chloride mixtures and switch from heating to sodium ion exchange; track atom/charge balances and limits.', [
    c('calcium-carbonate-magnesium-sulfate', 'Ein vereinfachtes Wasser enthält 1,0 mmol/L Ca(HCO₃)₂ und 0,5 mmol/L MgSO₄. Ordne die Härteanteile zu. Das Modell entfernt beim Erhitzen den Calciumhydrogencarbonatanteil vollständig, nicht das Magnesiumsulfat. Formuliere die Calciumreaktion und bestimme die verbleibende Härte.', 'Simplified water contains1.0 mmol/L Ca(HCO₃)₂ and0.5 mmol/L MgSO₄. Classify hardness portions. The model removes the calcium hydrogencarbonate portion completely by heating, not magnesium sulfate. Write calcium precipitation and determine remaining hardness.', 'Temporär 1,0, permanent 0,5 und gesamt 1,5 mmol/L zweiwertige Härtebildner. Ca²⁺ +2 HCO₃⁻ → CaCO₃(s) +CO₂ +H₂O; nach der ausdrücklich vorgegebenen vollständigen Modellfällung verbleiben 0,5 mmol/L. Daraus wird keine universelle Magnesiumcarbonatfällung oder reale vollständige Enthärtung behauptet.', 'Temporary1.0, permanent0.5 and total1.5 mmol/L divalent hardness cations. Ca²⁺ +2 HCO₃⁻ → CaCO₃(s) +CO₂ +H₂O; the explicitly complete model precipitation leaves0.5 mmol/L. This does not assert universal magnesium-carbonate precipitation or actual complete softening.', 'Härteanteile und begrenzte thermische Wirkung.', 'Hardness portions and bounded heating effect.'),
    c('chloride-water-ion-exchange', 'Frisch gegeben sind 0,75 mmol/L CaCl₂ und 0,25 mmol/L MgCl₂. Ein vorgegebenes Harz tauscht jedes zweiwertige Ion gegen zwei Na⁺ aus. Erkläre, warum bloßes Erhitzen hier nicht wie im vorigen Calciumhydrogencarbonatmodell wirkt; bilanziere Austausch und verbleibende Ionen.', 'Fresh water contains0.75 mmol/L CaCl₂ and0.25 mmol/L MgCl₂. Supplied resin exchanges each divalent ion for two Na⁺. Explain why heating does not act as in the preceding calcium-hydrogencarbonate model; balance exchange and remaining ions.', 'Im Modell permanente Gesamthärte 1,0 mmol/L; kein Hydrogencarbonat für den genannten Fällungsweg. Vollständiger vorgegebener Austausch ersetzt Ca/Mg durch 2,0 mmol/L Na⁺ bei unverändertem Chlorid. Härte fällt im Modell auf null, aber das Wasser enthält weiterhin Ionen und ist nicht entsalzt.', 'Model permanent total hardness is1.0 mmol/L; no hydrogencarbonate supports that precipitation route. Complete supplied exchange replaces Ca/Mg with2.0 mmol/L Na⁺ while chloride remains. Model hardness reaches zero but ions remain, so water is not demineralized.', 'Frischer Gegenion-/Verfahrenstransfer.', 'Fresh counterion and process transfer.')])

add('e9ea1606-5018-5a36-9ac2-8359747a65d4', 'data', [
    e('primary-ultimate-biodegradation', 'Primärer biologischer Abbau verändert den Ausgangsstoff; vollständige aerobe Mineralisierung betrifft den weiteren Abbau zu einfachen Endprodukten wie CO₂ und Wasser. Verlust von Tensidfunktion allein beweist keine vollständige Mineralisierung.', 'Primary biodegradation changes the parent compound; ultimate aerobic mineralization concerns further breakdown into simple products such as CO₂ and water. Loss of surfactant function alone does not prove complete mineralization.', 'Geeignete vorgegebene Messgrößen für Ausgangsstoffverlust und Mineralisierung unterscheiden und den jeweils erlaubten Schluss benennen.', 'Distinguish supplied measures of parent loss and mineralization and state their respective evidential limits.'),
    e('controlled-bio-test', 'Ein biologischer Abbaubefund benötigt passende Mikroorganismen, Bedingungen und Kontrollen. Adsorption oder ein ungeeigneter Test kann den Ausgangsstoff scheinbar entfernen, ohne biologischen Abbau zu beweisen.', 'A biodegradation finding needs appropriate microorganisms, conditions and controls. Adsorption or an unsuitable test can apparently remove the parent without proving biodegradation.', 'Kontrollierte vorgegebene Testdaten über Zeit, Ausgangsstoff und CO₂/Sauerstoffverbrauch vergleichen; Umwelt- oder Gesetzesfreigaben daraus nicht erfinden.', 'Compare controlled supplied test data over time, parent compound and CO₂/oxygen use without inventing environmental or statutory clearance.')],
    'Anderer Tensidstoff und Testbedingungen; Ausgangsstoffmessung gegen Mineralisierung und unbelebte Blindkontrolle.', 'Change surfactant and test conditions; compare parent measurement with mineralization and an abiotic blank.', [
    c('loss-versus-mineralization', 'Ein ausdrücklich didaktisches Testmodell meldet 80 % Verlust des Ausgangstensids, aber nur 15 % des theoretisch möglichen CO₂ nach gleicher Zeit. Erläutere primären und vollständigen Abbau und benenne, welche zusätzlichen Kontrollinformationen für eine biologische Deutung nötig sind.', 'An explicitly educational test model reports80% parent-surfactant loss but only15% of theoretical CO₂ after equal time. Explain primary and ultimate degradation and identify additional controls needed for a biological interpretation.', 'Ausgangsstoffverlust und CO₂-Mineralisierung sind verschiedene Messgrößen. 15 % belegt keine vollständige Mineralisierung; ohne unbelebte/Adsorptions- und Inokulumblindkontrolle ist selbst der primäre biologische Anteil nicht gesichert. Keine gesetzliche Grenzzahl oder Unbedenklichkeit wird aus diesen Modellzahlen abgeleitet.', 'Parent loss and CO₂ mineralization are different measures.15% does not establish complete mineralization; without abiotic/adsorption and inoculum blanks even the primary biological share is uncertain. No statutory threshold or harmlessness follows from these model numbers.', 'Messkriterium und Schlussgrenze.', 'Measurement criterion and inference limit.'),
    c('controlled-two-surfactants', 'Frische Daten vergleichen zwei Tenside bei gleichem eingesetzten organischen Kohlenstoff, Inokulum, Temperatur und Sauerstoffangebot. Nach Blindwertkorrektur zeigt A mehr CO₂ als B; eine zusätzliche unbelebte Kontrolle zeigt bei B starken Ausgangsstoffverlust ohne CO₂-Anstieg. Bewerte nur den durch die Daten belegten Unterschied.', 'Fresh data compare two surfactants at equal organic carbon, inoculum, temperature and oxygen supply. After blank correction A yields more CO₂ than B; an additional abiotic control shows strong parent loss for B without CO₂ increase. Evaluate only the supported difference.', 'Unter den gegebenen Bedingungen hat A einen höheren belegten aeroben Mineralisierungsanteil. Bei B erklärt die unbelebte Kontrolle einen möglichen nichtbiologischen Verlust. Das beweist weder allgemeine Persistenz in jedem Milieu noch Sicherheit von A; Bedingungen und Testdauer begrenzen den Vergleich.', 'Under these conditions A has a higher demonstrated aerobic mineralization fraction. B’s abiotic control supports possible nonbiological loss. This proves neither universal persistence in every environment nor safety of A; conditions and duration limit the comparison.', 'Frischer Kontroll-/Bedingungstransfer.', 'Fresh control and condition transfer.')])

add('33e845cc-1a7b-50d5-99b3-8079575c4e6a', 'concept', [
    e('preservation-mechanisms', 'Historisch verbreitete Verfahren wie Trocknen, Salzen oder Säuern und moderne Prozess-/Verpackungstechniken beeinflussen Wasserverfügbarkeit, pH, Temperatur oder Gasumgebung. Die Einordnung historisch/modern allein erklärt keine Wirkung.', 'Historically widespread drying, salting or acidification and modern processing/packaging affect water availability, pH, temperature or gas composition. Historical/modern labels alone do not explain action.', 'Vorgegebene Verfahren gegenüberstellen und die zum jeweiligen Modell passende Wachstumshemmung bzw. thermische Inaktivierung erklären.', 'Compare supplied procedures and explain model-specific growth inhibition or thermal inactivation.'),
    e('conditional-risk-comparison', 'Konservierungswirkung ist bedingt durch Verfahren, Ausgangsprodukt und Organismen. Hemmung ist nicht notwendig Sterilisation; Risiken können etwa verbleibendes Wachstum, Wiederverunreinigung oder Qualitätsänderung sein.', 'Preservation depends on process, initial product and organisms. Inhibition is not necessarily sterilization; risks include remaining growth, recontamination or quality changes.', 'Aus bereitgestellten Prozess-/Beobachtungsdaten Grenzen und Risiken verschiedener Methoden benennen, ohne Haltbarkeitsfristen oder Gesundheitsfreigaben zu erfinden.', 'Identify limitations and risks from supplied process/observation data without inventing shelf lives or health clearance.')],
    'Neue Lebensmittelmodelle und Verfahrenskombinationen; Wirkmechanismus und belegte Grenzen statt pauschale Sicherheitsrangfolge.', 'Use fresh food models and process combinations; compare mechanisms and evidenced limits instead of a blanket safety ranking.', [
    c('historical-and-modern-comparison', 'Eine didaktische Tabelle vergleicht Trocknen/Salzen und Säuern mit Kühlung und einem vorgegebenen Wärmeprozess. Messdaten zu Wasseraktivität, pH, Temperatur und modellhaftem Wachstum liegen vor. Ordne Wirkprinzipien zu und benenne für jedes Verfahren eine durch die Daten begründete Grenze.', 'An educational table compares drying/salting and acidification with cooling and a supplied heat process. Water activity, pH, temperature and model growth data are given. Assign mechanisms and identify a data-supported limit for each.', 'Trocknen/Salzen vermindert verfügbare Wasseraktivität, Säuern verändert pH, Kühlung verlangsamt im gegebenen Modell Wachstum, Wärme kann Organismen gemäß den vorgegebenen Daten inaktivieren. Hemmung wird nicht mit vollständiger Keimfreiheit gleichgesetzt; Restwachstum, Wiederverunreinigung oder Qualitätsänderung werden stoff-/prozessbezogen erklärt.', 'Drying/salting lowers available water activity, acidification changes pH, cooling slows model growth, and heat can inactivate organisms according to supplied data. Inhibition is not equated with sterility; remaining growth, recontamination or quality change are explained for the product/process.', 'Wirkmechanismen und Grenzen vergleichen.', 'Compare mechanisms and limits.'),
    c('changed-packaging-organisms', 'Frische Modellverpackungsdaten zeigen weniger Sauerstoff und geringeres Wachstum eines aeroben Organismus, aber Wachstum eines ausdrücklich vorgegebenen anderen Organismus. Vergleiche dieses moderne Verfahren mit Säuern/Trocknen anhand einer zweiten Datentabelle und begründe eine Grenze; keine Anwendungsempfehlung oder reale Haltbarkeit.', 'Fresh packaging-model data show lower oxygen and reduced growth of an aerobic organism but growth of another explicitly supplied organism. Compare the modern process with acidification/drying using a second table and explain a limitation; no application advice or actual shelf life.', 'Verminderter Sauerstoff betrifft bestimmte Wachstumsbedingungen, nicht alle Organismen gleichermaßen. Die vorgegebenen Daten widerlegen einen allgemeinen Sterilitätsanspruch. Säuern/Trocknen wirken über andere Bedingungen; Kombinationen sind nur im Umfang vorhandener Daten bewertbar, nicht automatisch sicher.', 'Lower oxygen affects particular growth conditions rather than every organism equally. Supplied data contradict a universal sterility claim. Acidification/drying act through other conditions; combinations can be evaluated only within available data and are not automatically safe.', 'Frischer Organismen-/Verfahrensvergleich.', 'Fresh organism and process comparison.')])

add('db66635f-f1d1-5f70-bcc0-fed1ae424e52', 'experiment', [
    e('perform-qualitative-controlled-test', 'Ein qualitativer Nachweis verlangt geeignete Durchführung, Blind-/Vergleichskontrollen und Beobachtung. Die Farbe des DCPIP-Reagenzes hängt auch vom pH ab; ein positiver Reduktionsbefund ist nicht automatisch substanzspezifisch.', 'A qualitative test requires appropriate execution, blanks/comparators and observation. DCPIP reagent color also depends on pH; a positive reduction finding is not automatically substance-specific.', 'Eine freigegebene betreute Nachweisvorschrift mit Kontrollen tatsächlich durchführen, eigene Beobachtungen dokumentieren und den erlaubten qualitativen Schluss ziehen.', 'Actually perform an approved supervised detection protocol with controls, document observations and draw the permitted qualitative conclusion.'),
    e('redox-antioxidant-model', 'Ascorbinsäure kann Elektronen abgeben, wird dabei oxidiert und reduziert das Nachweisreagenz. Das erklärt eine antioxidative Wirkung in diesem chemischen Modell, nicht jeden biologischen oder gesundheitlichen Effekt.', 'Ascorbic acid can donate electrons, becoming oxidized while reducing the detection reagent. This explains antioxidant action in this chemical model rather than every biological or health effect.', 'Elektronendonator/-akzeptor im konkreten Versuch bestimmen, Reduktion des Reagenzes mit Oxidation der Ascorbinsäure verbinden und Störungen bzw. Nachweisgrenzen erklären.', 'Identify electron donor/acceptor in the experiment, connect reagent reduction to ascorbic-acid oxidation and explain interference or detection limits.')],
    'Frisches freigegebenes Reagenz-/Probenmodell mit eigenen betreuten Handgriffen, pH-kontrollierten Vergleichen und möglichen anderen Reduktionsmitteln.', 'Use a fresh approved reagent/sample model with actual supervised actions, pH-controlled comparisons and possible other reducing agents.', [
    c('controlled-dcpip-detection', 'Führe unter Aufsicht die freigegebene qualitative DCPIP-Vorschrift mit Reagenzblindprobe, bekannter Ascorbinsäure und vorgegebener unbekannter Probe durch. Alle Vergleiche sind pH-kontrolliert; das oxidierte Reagenz ist im vorgegebenen neutralen Modell blau. Dokumentiere Durchführung und Farbverlauf und erkläre den chemischen Schluss.', 'Under supervision carry out the approved qualitative DCPIP protocol with a reagent blank, known ascorbic acid and supplied unknown. Comparisons control pH; oxidized reagent is blue in the given neutral model. Record actions and color changes and explain the chemical inference.', 'Zukünftiger Leistungsbeleg enthält eigene sachgerechte Durchführung/Beobachtung. Entfärbung gegenüber Kontrollen zeigt Reduktion; Ascorbinsäure gibt Elektronen ab und wird oxidiert. Andere Reduktionsmittel oder ungleicher pH können die Zuordnung stören; ohne zusätzliche Selektivitätsdaten ist die unbekannte Probe nicht eindeutig identifiziert, und ohne Kalibrierung ist keine Konzentration bestimmt.', 'Future evidence includes actual appropriate execution/observation. Decolorization against controls shows reduction; ascorbic acid donates electrons and is oxidized. Other reducers or unequal pH can interfere; absent selectivity data the unknown is not uniquely identified, and without calibration no concentration is established.', 'Praktischer qualitativer Nachweis mit Redoxdeutung.', 'Practical qualitative detection with redox interpretation.'),
    c('fresh-iodine-comparison', 'Eine frische freigegebene betreute Aufgabe verwendet ein vorgegebenes Iod/Stärke-Reagenzmodell mit passenden Blind-/Ascorbinsäurekontrollen und einer möglichen anderen reduzierenden Substanz. Führe die zulässigen Prüfschritte aus, dokumentiere den Farbverlauf und verbinde I₂/2I⁻ mit C₆H₈O₆/C₆H₆O₆ in einer ladungsrichtigen Redoxbilanz.', 'A fresh approved supervised task uses a supplied iodine/starch model with blanks/ascorbic-acid controls and a possible other reducing substance. Perform permitted steps, record color changes and connect I₂/2I⁻ with C₆H₈O₆/C₆H₆O₆ in a charge-balanced redox equation.', 'I₂ +2e⁻ →2I⁻ und C₆H₈O₆ →C₆H₆O₆ +2H⁺ +2e⁻ ergeben C₆H₈O₆ +I₂ →C₆H₆O₆ +2H⁺ +2I⁻. Verlust der Iod/Stärke-Färbung passt zur Reagenzreduktion; die andere reduzierende Substanz begrenzt Selektivität. Eigene Durchführung bleibt erforderlich, die Daten ersetzen sie nicht; keine allgemeine Gesundheits- oder Unbedenklichkeitsbehauptung.', 'I₂ +2e⁻ →2I⁻ and C₆H₈O₆ →C₆H₆O₆ +2H⁺ +2e⁻ yield C₆H₈O₆ +I₂ →C₆H₆O₆ +2H⁺ +2I⁻. Loss of iodine/starch color fits reagent reduction; another reducing substance limits selectivity. Actual execution remains necessary and is not replaced by data; no general health or harmlessness claim.', 'Frischer Reagenz-/Interferenztransfer.', 'Fresh reagent and interference transfer.')])

def write_candidates():
    model = json.loads((SOURCE / 'native-finalbook/bundle/book-model.json').read_text())
    wanted = [x['goalId'] for x in model['pages'][:-1]]
    assert [x['goalId'] for x in rows] == wanted, 'Exact fourteen scope/order required before export'
    out = dict(schemaVersion=1, authoringContract='positive-understanding-evidence-candidates-v1',
        reviewId='chemie-q1-fourteen-current-20261005-p-author-v2',
        reviewedAt=datetime.now(timezone.utc).isoformat(), reviewer='root-q1-informed-positive-profile-author', goals=rows)
    (OWN / 'positive-evidence.candidates.json').write_text(json.dumps(out, ensure_ascii=False, indent=2)+'\n')
    (OWN / 'author-input-binding.receipt.json').write_text(json.dumps(dict(status='inactive_author_candidates_independent_review_pending',
        sourceBookModelPath=str((SOURCE/'native-finalbook/bundle/book-model.json').relative_to(ROOT)),
        sourceBookModelSHA256=hashlib.sha256((SOURCE/'native-finalbook/bundle/book-model.json').read_bytes()).hexdigest(),
        profileCount=len(rows), strictClosure=0, humanApproval=False, observedLearnerPerformance=False,
        practicalOperatorsRetained=True, sourceHoldsClosed=0), ensure_ascii=False, indent=2)+'\n')

if __name__ == '__main__':
    write_candidates()
